const N=90;
const K=TAU*2/W;
const A=H*0.21;
const spd=0.09;
path("mid", {x: 0, y: 0, points: [0,H/2,W,H/2], stroke: "soft", strokeWidth: 5, fill: "none", opacity: 0.9});
path("w1", {x: 0, y: 0, points: [0,H/2,W,H/2], stroke: "ink", strokeWidth: 7, fill: "none"});
path("w2", {x: 0, y: 0, points: [0,H/2,W,H/2], stroke: "accent", strokeWidth: 7, fill: "none", opacity: 0});
path("s", {x: 0, y: 0, points: [0,H/2,W,H/2], stroke: "highlight", strokeWidth: 12, fill: "none", opacity: 0});
key("w2", "opacity", T0, 0);
key("w2", "opacity", args.send, 0);
key("w2", "opacity", args.send+8, 1, "smooth");
key("s", "opacity", T0, 0);
key("s", "opacity", args.sumShow, 0);
key("s", "opacity", args.sumShow+8, 1, "smooth");
function shiftAt(f) { if (f <= args.slide0) return 0; if (f >= args.slide1) return Math.PI; return Math.PI*smooth((f-args.slide0)/Math.max(1,args.slide1-args.slide0)); }
function ph(f) { return -(f-T0)*spd; }
anim("w1", "points", T0, T1, (t,f) => { const p=[]; const o=ph(f); for (let i=0;i<=N;i++) { const x=W*i/N; const y=H/2+A*Math.sin(K*x+o); p.push(x,y); } return p; }, 3);
anim("w2", "points", T0, T1, (t,f) => { const p=[]; const o=ph(f)+shiftAt(f); for (let i=0;i<=N;i++) { const x=W*i/N; const y=H/2+A*Math.sin(K*x+o); p.push(x,y); } return p; }, 3);
anim("s", "points", T0, T1, (t,f) => { const p=[]; const o=ph(f); const e=shiftAt(f); for (let i=0;i<=N;i++) { const x=W*i/N; const y1=A*Math.sin(K*x+o); const y2=A*Math.sin(K*x+o+e); p.push(x,H/2+y1+y2); } return p; }, 3);
